const data={"sources":{"ext20261006_resp2_ptx_rch":{"name":"Royal Children's Hospital / Paediatric Improvement Collaborative — Primary spontaneous pneumothorax","url":"https://www.rch.org.au/clinicalguide/guideline_index/Primary_spontaneous_pneumothorax/","author":"Royal Children's Hospital Melbourne; Paediatric Improvement Collaborative (autoria institucional)","documentDate":"2023-11","population":"Crianças e adolescentes; diretriz pediátrica","locators":["Key Points","Background","Assessment > History","Assessment > Tension Pneumothorax","Consider consultation with local paediatric team when","Consider discharge when"],"support":"Distingue pneumotórax espontâneo de apresentação hipertensiva; decisão pela repercussão clínica. A melhora da dor não garante resolução. Alta requer estabilidade e retorno organizado.","checked":"2026-10-06"},"ext20261006_resp2_ptx_nch":{"name":"Nationwide Children's Hospital — Spontaneous Pneumothorax, Helping Hands HH-I-709","url":"https://www.nationwidechildrens.org/conditions/spontaneous-pneumothorax","author":"Equipe médica, de enfermagem e multiprofissional do Nationwide Children's Hospital (autoria institucional declarada)","documentDate":"2024","dateNote":"Ano do material HH-I-709; não há data de revisão mais precisa na página.","population":"Orientação familiar pediátrica","locators":["Overview","Risk Factors","Treatment","Care at Home","When to Call the Doctor","When to Call 911"],"support":"Ar no espaço pleural; fatores de risco; alguns casos têm observação médica. Orienta liberação individual para esporte, peso, voo e mergulho em piscina, e reavaliação diante de piora.","checked":"2026-10-06"},"ext20261006_resp2_abscesso_ct":{"name":"Connecticut Children's — Lung Abscess, Pediatric Surgery","url":"https://www.connecticutchildrens.org/specialties-conditions/pediatric-surgery/conditions/lung-abscess","author":"Connecticut Children's, Pediatric Surgery (autoria institucional)","documentDate":null,"dateNote":"Sem data de publicação ou revisão visível no conteúdo consultado.","population":"Pediátrica","locators":["Introdução","What are the signs and symptoms of a lung abscess?","What causes a lung abscess?","How is a lung abscess treated?"],"support":"Coleção de pus no tecido pulmonar, frequentemente após pneumonia; febre, tosse, dor e dificuldade respiratória. Plano definido pela equipe.","checked":"2026-10-06"},"ext20261006_resp2_cap_rch":{"name":"Royal Children's Hospital / Paediatric Improvement Collaborative — Community acquired pneumonia","url":"https://www.rch.org.au/clinicalguide/guideline_index/Community_acquired_pneumonia/","author":"Royal Children's Hospital Melbourne; Paediatric Improvement Collaborative (autoria institucional)","documentDate":"2023-10","population":"Pediátrica; recém-nascidos têm avaliação própria","locators":["Background","Assessment > Assessment of severity","Management > Investigations > CXR","Consider consultation with local paediatric team when","Consider transfer when","Consider discharge when"],"support":"Abscesso integra pneumonia complicada; falha de melhora ou piora exige reavaliação. Complicações e comorbidades precisam de avaliação pediátrica; acompanhamento pode incluir imagem.","checked":"2026-10-06"},"ext20261006_resp2_atelectasia_child":{"name":"Valley Children's Pediatric HealthHub — Atelectasis (Child)","url":"https://health.valleychildrens.org/lung-health/sintomas/atelectasis-child","author":"The StayWell Company; revisores Chris Southard RN, Marianne Fraser MSN RN e Sravani Chintapalli; publicado no portal institucional Valley Children’s","documentDate":"2025-01-01","dateNote":"Date Last Reviewed: 01/01/2025.","population":"Crianças e famílias","locators":["Introdução, parágrafos sobre causas e gravidade","Home care > General care","Follow-up care","When to call your doctor","Call 911"],"support":"Atelectasia pode ser pequena e assintomática; crianças pequenas e com doenças prévias têm maior risco. Exercícios apenas como ensinados; sintomas persistentes/piores exigem retorno.","checked":"2026-10-06"},"ext20261006_resp2_atelectasia_extent":{"name":"Penn Medicine — Atelectasis","url":"https://www.pennmedicine.org/conditions/atelectasis","author":"Allen J. Blaivas DO; revisão VeriMed Healthcare Network, David C. Dugdale MD, Brenda Conaway e equipe editorial A.D.A.M.; portal Penn Medicine","documentDate":"2024-08-19","population":"Geral; usada somente para a distinção anatômica e o alerta explícito sobre áreas extensas em bebês e crianças pequenas","locators":["Definition","Causes","Symptoms","Outlook (Prognosis)","When to Contact a Medical Professional"],"support":"Área extensa pode ameaçar a vida, especialmente em criança pequena; não equivale à atelectasia pequena. Pneumotórax e atelectasia são conceitos diferentes.","limitation":"Fonte institucional complementar, não exclusivamente pediátrica; triangulada com material pediátrico Valley Children’s e RCH. Nenhuma conduta adulta foi transposta.","checked":"2026-10-06"},"ext20261006_resp2_corpoestranho_rch":{"name":"Royal Children's Hospital / Paediatric Improvement Collaborative — Foreign bodies inhaled","url":"https://www.rch.org.au/clinicalguide/guideline_index/Foreign_bodies_inhaled/","author":"Royal Children's Hospital Melbourne; Paediatric Improvement Collaborative (autoria institucional)","documentDate":"2021-03","population":"Pediátrica","locators":["Key points","Assessment > History","Assessment > Impaction in main bronchus","Management > Investigations","Consider consultation with ENT or respiratory team when"],"support":"Engasgo pode ter ocorrido dias ou semanas antes; obstrução pode causar colapso pulmonar e abscesso. História de aspiração merece ser comunicada mesmo após melhora aparente.","checked":"2026-10-06"},"ext20261006_resp2_had_ats":{"name":"American Thoracic Society — Pediatric Anemia: A Bloody Mess","url":"https://site.thoracic.org/assemblies/cp/ats-quick-hits/pediatric-anemia-a-bloody-mess","author":"Kevin Kaplan MD, Amee Revana DO e David R. Spielberg MD; Baylor College of Medicine/Texas Children’s Hospital","documentDate":null,"dateNote":"Sem data de publicação/revisão visível; consulta atual de material clínico educacional da ATS.","population":"Caso pediátrico e discussão de hemorragia alveolar; material profissional educacional","locators":["Authors","Case","Answer > Discussion, parágrafos sobre causas, sintomas e história","Answer > Discussion, investigação e suporte hospitalar"],"support":"Pode haver anemia e palidez sem sangue visível na tosse. Histórico de episódios, infecções, engasgos, exposições e sangramento em outros órgãos ajuda a investigação.","limitation":"Caso educacional, não diretriz abrangente. A ficha familiar não reproduz procedimentos, exames obrigatórios ou terapias.","checked":"2026-10-06"},"ext20261006_resp2_had_nch":{"name":"Pediatrics Nationwide — Exploring Pediatric Diffuse Alveolar Hemorrhage: Causes and Outcomes","url":"https://pediatricsnationwide.org/2024/12/27/exploring-pediatric-diffuse-alveolar-hemorrhage-causes-and-outcomes/","author":"Erin Gregory; entrevista com as investigadoras Sarah P. Cohen MD MS e Katelyn Krivchenia MD, Nationwide Children’s Hospital","documentDate":"2024-12-27","population":"Pediátrica; divulgação institucional da pesquisa do próprio hospital","locators":["Introdução","Key Mortality and Recovery Findings","Diagnostic and Treatment Challenges","Implications for Future Research and Care"],"support":"Hemorragia alveolar pode ser grave e precisar de suporte especializado urgente; causas e evolução variam. Sangue na tosse não está presente em todos os casos, nem confirma sozinho o diagnóstico.","limitation":"Relato institucional de estudo retrospectivo com os próprios pesquisadores. Não utilizado para inferir efeito de tratamento ou prognóstico individual.","checked":"2026-10-06"},"ext20261006_resp2_gravidade_rch":{"name":"Royal Children's Hospital / Paediatric Improvement Collaborative — Assessment of severity of respiratory conditions","url":"https://www.rch.org.au/clinicalguide/guideline_index/Assessment_of_severity_of_respiratory_conditions/","author":"Royal Children's Hospital Melbourne; Paediatric Improvement Collaborative (autoria institucional)","documentDate":"2024-09","population":"Pediátrica","locators":["Key points","Assessment > Behaviour, Colour, Respiratory rate, Increased work of breathing","Signs of increased work of breathing","Other considerations","Consider consultation with local paediatric team when"],"support":"Menor manipulação na dificuldade respiratória; esforço importante, pausas, alteração da consciência e cianose são sinais críticos. A aparência clínica importa mesmo com oxímetro aparentemente normal.","checked":"2026-10-06"},"ext20261006_resp2_samu":{"name":"Ministério da Saúde — Serviço de Atendimento Móvel de Urgência, SAMU 192","url":"https://www.gov.br/saude/pt-br/composicao/saes/samu-192","author":"Ministério da Saúde, Secretaria de Atenção Especializada à Saúde (autoria institucional)","documentDate":null,"dateNote":"Sem data de atualização visível na página consultada.","population":"População brasileira; inclui crianças","locators":["Quando Chamar o SAMU 192?","QUANDO CHAMAR","Dicas para quem ligar para o SAMU 192"],"support":"192 presta orientação e aciona atendimento para emergências, inclusive cardiorrespiratórias; seguir o médico regulador.","checked":"2026-10-06"},"ext20261006_resp2_empiema_rch":{"name":"Royal Children's Hospital / Paediatric Improvement Collaborative — Parapneumonic effusion","url":"https://www.rch.org.au/clinicalguide/guideline_index/Parapneumonic_effusion/","author":"Royal Children's Hospital Melbourne; Paediatric Improvement Collaborative (autoria institucional)","documentDate":"2022-08","checked":"2026-10-06","population":"Pediátrica","locators":["Background"],"support":"Empiema é infecção no espaço pleural, anatomicamente diferente de abscesso dentro do pulmão; usado apenas para essa distinção."},"supp_colic_sbp2023":{"name":"SBP — Cólica do lactente","url":"https://www.sbp.com.br/pediatria-para-familias/primeira-infancia/colica-do-lactente/","author":"Departamento Científico de Gastroenterologia Pediátrica","sourceDate":"2023-07","checked":"2026-10-06","locator":"O que pode ser feito em casa para ajudar no controle da cólica do lactente?, lista linhas 90–102","excerpt":"Flexionar as coxas do bebê sobre a barriga","supports":"Lista histórica localizada na fonte institucional original. Trata medidas como sugestões, sem assegurar eficácia nem ensinar manobra ou compressa com parâmetros de segurança.","limitations":"Recomendação educativa de 2023, não ensaio nem validação de técnica domiciliar. Precisa ser complementada por sono seguro atual."},"supp_sleep_aap2026":{"name":"AAP/HealthyChildren — How to Keep Your Sleeping Baby Safe: AAP Policy Explained","url":"https://www.healthychildren.org/English/ages-stages/baby/sleep/Pages/A-Parents-Guide-to-Safe-Sleep.aspx","author":"Rachel Y. Moon, MD, FAAP","sourceDate":"2026-09-11","checked":"2026-10-06","locator":"Place your baby on their back; Choose a firm, flat sleep surface; Swaddle your baby if you like, linhas 147–156; Last Updated 9/11/2026","excerpt":"When your baby looks like they’re trying to roll over, you should stop swaddling them.","supports":"Sono supino, superfície firme/plana, não dormir com cuidador; envolvimento opcional, sem peso e sem restrição de respiração/quadris; interromper ao tentar rolar.","limitations":"Segurança do sono, não prova de eficácia para cólica. Data da página americana interpretada como 11 de setembro."},"supp_swaddle_aap2022":{"name":"AAP/HealthyChildren — Swaddling: Is it Safe for Your Baby?","url":"https://www.healthychildren.org/English/ages-stages/baby/diapers-clothing/Pages/Swaddling-Is-it-Safe.aspx","author":"Rachel Y. Moon, MD, FAAP; Danette Glassy, MD, FAAP","sourceDate":"2022-07-15","checked":"2026-10-06","locator":"When to stop swaddling; AAP safe sleep recommendations; Keep hips loose; How to swaddle correctly, linhas 60–105","excerpt":"Use only a thin blanket for swaddling.","supports":"Manta fina, cabeça descoberta, quadris/pernas livres para flexionar, não apertar peito, risco de tecido solto e superaquecimento.","limitations":"Página mais antiga, usada para detalhes compatíveis com a política explicada AAP atualizada em set/2026; não generalizar para bebê que tenta rolar."},"supp_contact_ouh2025":{"name":"Oxford University Hospitals NHS — Skin-to-skin contact: why it is important, and how to do it safely","url":"https://www.ouh.nhs.uk/media/dhrjjlsi/114078contact.pdf","author":"Consultant Midwife, Oxford University Hospitals","sourceDate":"2025-07","reviewDue":"2028-07","checked":"2026-10-06","locator":"Página 3, Safety points; página 8, autoria e revisão","excerpt":"their head is upright and to one side","supports":"Contato ventral junto ao tronco com cabeça/pescoço apoiados, vias aéreas livres e cuidador atento; ao sentir sono, colocar bebê em espaço seguro.","limitations":"Orientação de contato pele a pele neonatal, não demonstra benefício terapêutico específico para cólica. A adaptação familiar limita o contato ao bebê e cuidador acordados."},"supp_settling_rch2025":{"name":"RCH/PIC — Unsettled or crying babies","url":"https://www.rch.org.au/clinicalguide/guideline_index/Crying_Baby_Infant_Distress/","author":"Royal Children’s Hospital / Paediatric Improvement Collaborative","sourceDate":"2025-10","checked":"2026-10-06","locator":"Management approach, item 5; Feeding-related interventions, linhas 163–165; Practical strategies, linhas 211–238","excerpt":"Flexible, on-demand feeding","supports":"Medidas flexíveis, resposta aos sinais do bebê, alimentação em livre demanda, música de baixo volume, contato e banho como experiências de conforto.","limitations":"Não prescreve rotina rígida nem comprova benefício isolado de flexionar coxas para cólica."},"supp_cry_nhs2026":{"name":"NHS — Soothing a crying baby","url":"https://www.nhs.uk/baby/caring-for-a-newborn/soothing-a-crying-baby/","author":"NHS","sourceDate":"2026-04-22","checked":"2026-10-06","locator":"How to calm a crying baby; Getting help with a crying baby; Never shake your baby","excerpt":"Sometimes too much rocking and singing can keep your baby awake.","supports":"Consolo suave, banho conforme aceitação, reduzir excesso de estimulação e nunca sacudir.","limitations":"Respostas variam; banho e música não curam cólica nem justificam postergar avaliação."},"supp_bath_nhs2026":{"name":"NHS — Baby and toddler safety","url":"https://www.nhs.uk/baby/first-aid-and-safety/safety/baby-and-toddler-safety/","author":"NHS","sourceDate":"2026-02-19","checked":"2026-10-06","locator":"Burns and scalds, linhas 95–98; Drowning, linhas 108–112","excerpt":"A baby’s skin burns more easily than an adult’s.","supports":"Testar água antes do banho e permanecer junto; pele do bebê sofre queimadura com facilidade.","limitations":"Fonte de prevenção, não endosso de compressas térmicas."},"supp_heat_nhs":{"name":"NHS Best Start in Life — How to dress a newborn baby","url":"https://www.nhs.uk/best-start-in-life/baby/baby-basics/caring-for-your-baby/how-to-dress-a-newborn/","author":"NHS","sourceDate":null,"checked":"2026-10-06","locator":"Safe room temperature; lista Babies should","excerpt":"never sleep with a hot water bottle or electric blanket","supports":"Evitar fontes de calor e superaquecimento no bebê.","limitations":"Data editorial não exibida na leitura; usado com orientação NHS de prevenção revisada em 2026. Excluir compressa aquecida da ficha é escolha conservadora por ausência de técnica segura padronizada nas fontes de cólica, não alegação de contraindicação universal de toda compressa."},"supp_wind_nhs":{"name":"NHS Best Start in Life — How to burp your baby","url":"https://www.nhs.uk/best-start-in-life/baby/feeding-your-baby/bottle-feeding/bottle-feeding-your-baby/how-to-burp-your-baby/","author":"NHS","sourceDate":null,"checked":"2026-10-06","locator":"What if my baby cannot burp?, linhas 57–61","excerpt":"move your baby’s legs back and forth","supports":"Descreve movimento suave das pernas com bebê de costas no contexto de desconforto por ar deglutido.","limitations":"Não equivale a evidência específica para cólica nem permite prometer eliminação de gases; não é razão para iniciar força, compressão abdominal ou número fixo de repetições."}},"topics":[{"key":"ext_pneumotorax_espontaneo","label":"Pneumotórax espontâneo","parent":"Pneumotórax espontâneo","category":"Respiratório","detail":"Ar escapa para o espaço entre o pulmão e a parede do tórax sem um trauma desencadeante, podendo comprimir o pulmão.","aliases":["pneumotórax espontâneo","pneumotorax espontaneo","pneumotórax espontâneo primário","pneumotorax espontaneo primario","pneumotórax espontâneo secundário","pneumotorax espontaneo secundario"],"refs":["ext20261006_resp2_ptx_rch","ext20261006_resp2_ptx_nch","ext20261006_resp2_gravidade_rch","ext20261006_resp2_samu"],"urgency":true,"urgent":true,"triage":"Suspeita ou sintomas agudos: avaliação hospitalar sem demora. Sinais críticos: SAMU 192. Caso estável, já avaliado e liberado: plano de alta individual.","home":["Dor súbita no peito, especialmente de um lado, com ou sem falta de ar, precisa de avaliação hospitalar se houver suspeita de pneumotórax. A dor pode diminuir mesmo quando ainda existe ar ao redor do pulmão.","Enquanto busca atendimento, mantenha a criança acompanhada, em repouso e sem esforço. Evite movimentações desnecessárias se houver dificuldade respiratória."],"care":["Informe o início dos sintomas, episódios anteriores, doenças pulmonares, casos na família, uso de cigarro ou vape e qualquer trauma ou procedimento recente.","Nem todo pneumotórax espontâneo é hipertensivo. Alguns casos estáveis permitem observação médica; a forma hipertensiva compromete respiração e circulação e é emergência. Só a equipe pode avaliar essa diferença. Quando há doença pulmonar de base, o plano precisa de avaliação especializada."],"alarm":["Ligue 192 diante de falta de ar intensa, lábios azulados ou acinzentados, desmaio ou dificuldade para acordar. Siga as orientações do atendente.","Após a alta, procure retorno imediato ao pronto-socorro se a dor no peito voltar ou aumentar, ou se surgir dificuldade para respirar, mesmo que o episódio anterior tenha sido pequeno."],"follow":["Antes de sair, confirme quando será a reavaliação e quais exames serão necessários. O problema pode voltar; melhora da dor não substitui o acompanhamento.","Esportes, levantamento de peso, viagens aéreas e mergulho em piscina dependem de liberação médica. Evite cigarro e vape. Se houve procedimento, siga o cuidado da ferida indicado na alta e avise a equipe sobre febre, vermelhidão ou dor crescente."]},{"key":"ext_abscesso_pulmonar","label":"Abscesso pulmonar","parent":"Abscesso pulmonar","category":"Respiratório","detail":"Coleção de pus dentro do tecido do pulmão, geralmente ligada a uma infecção. É diferente do empiema, em que o pus fica ao redor do pulmão.","aliases":["abscesso pulmonar","abscesso de pulmão","abscesso de pulmao"],"refs":["ext20261006_resp2_abscesso_ct","ext20261006_resp2_cap_rch","ext20261006_resp2_empiema_rch","ext20261006_resp2_corpoestranho_rch","ext20261006_resp2_gravidade_rch","ext20261006_resp2_samu"],"urgency":true,"urgent":true,"triage":"Suspeita ou diagnóstico novo: avaliação hospitalar sem demora. Sinais críticos: SAMU 192. Cuidado após alta apenas conforme plano da equipe.","home":["Suspeita ou diagnóstico recente de abscesso pulmonar precisa de avaliação hospitalar. Febre, tosse, dor no peito e respiração difícil podem ocorrer; piora durante uma pneumonia exige reavaliação, sem esperar o retorno marcado.","Até o atendimento, mantenha a criança acompanhada, em repouso, evitando esforço e movimentações desnecessárias se estiver com falta de ar."],"care":["Leve exames e relate a evolução da febre e da tosse, tratamentos já recebidos, alergias e doenças pulmonares ou da imunidade. Conte sobre engasgos, mesmo que tenham ocorrido dias ou semanas antes.","A equipe precisa avaliar a extensão da infecção e possíveis complicações. Esta ficha não orienta tratamento caseiro nem permite iniciar, trocar ou encerrar o tratamento por conta própria."],"alarm":["Ligue 192 se houver esforço intenso para respirar, pausas respiratórias, lábios azulados ou acinzentados, desmaio ou pouca resposta. Siga as orientações do atendente.","Depois da alta, procure reavaliação sem demora se ocorrer qualquer um destes sinais: febre que reaparece; febre persistente com piora da disposição; dor crescente; respiração mais difícil; ou dificuldade para beber."],"follow":["O seguimento pode precisar de exames para verificar a recuperação e investigar a causa. Confirme o retorno com a equipe, mesmo que a criança melhore; a duração do acompanhamento e a volta à escola e às atividades dependem da evolução."]},{"key":"ext_atelectasia_pulmonar_massiva","label":"Atelectasia pulmonar massiva","parent":"Atelectasia pulmonar massiva","category":"Respiratório","detail":"Uma grande parte do pulmão perde ar e não se expande adequadamente. Pode acontecer por obstrução da passagem de ar ou compressão do pulmão.","aliases":["atelectasia pulmonar massiva","atelectasia massiva","atelectasia pulmonar extensa"],"refs":["ext20261006_resp2_atelectasia_child","ext20261006_resp2_atelectasia_extent","ext20261006_resp2_corpoestranho_rch","ext20261006_resp2_gravidade_rch","ext20261006_resp2_samu"],"urgency":true,"urgent":true,"triage":"Suspeita ou diagnóstico agudo de atelectasia extensa/massiva: avaliação hospitalar sem demora. Pequena atelectasia já avaliada não é automaticamente uma emergência.","home":["Esta ficha trata da forma extensa ou massiva: na suspeita aguda, procure avaliação hospitalar sem demora. Ela pode prejudicar a oxigenação, especialmente em bebês e crianças com outras doenças.","Uma pequena atelectasia pode não causar sintomas e ter outra orientação após avaliação. Não use a palavra “atelectasia” isolada em um laudo para concluir a gravidade nem para decidir o cuidado por conta própria.","Enquanto busca ajuda, mantenha a criança acompanhada e evite esforços e movimentações desnecessárias se houver dificuldade respiratória."],"care":["Informe se houve engasgo, cirurgia ou anestesia recente, dificuldade para eliminar secreções e doença pulmonar prévia. Engasgo antigo continua importante mesmo se a criança pareceu melhorar depois.","Não improvise manobras para “abrir o pulmão”. Exercícios respiratórios, aparelhos ou fisioterapia em casa só devem seguir indicação e treinamento da equipe, depois da avaliação."],"alarm":["Ligue 192 se houver falta de ar intensa, pausas na respiração, lábios azulados ou acinzentados, confusão, desmaio ou dificuldade para acordar. Siga as orientações do atendente.","Após a alta, respiração que piora, nova febre ou tosse crescente precisam de contato rápido com a equipe; diante de dificuldade respiratória importante, busque emergência."],"follow":["O retorno deve verificar a recuperação e a causa do colapso. Siga apenas os exercícios e cuidados ensinados, com frequência e duração definidas para a criança. Retorno às atividades e necessidade de novos exames dependem da evolução."]},{"key":"ext_hemorragia_alveolar_difusa","label":"Hemorragia alveolar difusa","parent":"Hemorragia alveolar difusa","category":"Respiratório","detail":"Sangramento dentro de muitas pequenas bolsas de ar dos pulmões, os alvéolos. Pode comprometer a respiração e provocar anemia.","aliases":["hemorragia alveolar difusa","sangramento alveolar difuso"],"refs":["ext20261006_resp2_had_ats","ext20261006_resp2_had_nch","ext20261006_resp2_gravidade_rch","ext20261006_resp2_samu"],"urgency":true,"urgent":true,"triage":"Suspeita ou apresentação aguda: avaliação hospitalar imediata. Sangramento com comprometimento respiratório ou da consciência: SAMU 192.","home":["Suspeita ou diagnóstico novo de hemorragia alveolar exige avaliação hospitalar imediata. Pode haver tosse com sangue, falta de ar, palidez ou cansaço; a ausência de sangue visível na tosse não exclui o problema.","Enquanto busca socorro, mantenha a criança acompanhada, sem esforço e com pouca movimentação. Não espere aparecer sangue na tosse para procurar atendimento se a respiração ou o estado geral estiverem piorando."],"care":["Conte quando os sintomas começaram, se houve sangue na tosse e em que quantidade aproximada, além de febre, engasgos, sangramentos em outros locais ou sangue na urina. Leve exames e a lista dos remédios em uso.","Informe doenças do coração ou pulmão, problemas de coagulação, doenças autoimunes e possíveis exposições a fumaças ou substâncias inaladas. Não é possível confirmar a causa só pela aparência do sangue ou pelos sintomas."],"alarm":["Ligue 192 se houver sangramento pela tosse com falta de ar importante, lábios azulados ou acinzentados, desmaio ou dificuldade para acordar; esses sinais também exigem socorro sem sangue visível. Siga as orientações do atendente.","Depois da alta, novo sangue na tosse, falta de ar ou aumento importante de palidez e cansaço exigem reavaliação imediata. Não espere a consulta marcada."],"follow":["Antes da alta, confirme o plano com a equipe e o especialista responsável. O acompanhamento é individual e pode avaliar a recuperação do pulmão, a anemia e a causa do sangramento; não altere o plano por conta própria ao perceber melhora."]},{"key":"ext_colica_lactente","label":"Cólica do lactente — após avaliação","parent":"Cólica do lactente — após avaliação","category":"Digestivo e nutrição","urgency":false,"aliases":["cólica do lactente","colica do lactente","cólica infantil","colica infantil","cólica do bebê","colica do bebe","Cólica do Lactente Aguda"],"coverage":{"type":"specific","pps_exact_label":"Cólica do Lactente Aguda","generic_replacements_forbidden":["dor abdominal inespecífica","refluxo fisiológico","constipação"]},"age":{"label":"Bebês com menos de 5 meses, após avaliação","minMonthsInclusive":0,"maxMonthsExclusive":5,"catalogBuckets":["u3m","3a5m"],"bucketWarning":"O grupo 3a5m inclui bebês de 5 meses: não autoriza automaticamente esta ficha. Conferir idade exata <5 meses; se indisponível, manter alerta explícito e solicitar revisão do diagnóstico.","onUnknownAge":"Não afirmar aplicabilidade; pedir conferência da idade antes de gerar orientação específica.","onOutOfRange":"Não atribuir o choro a cólica do lactente; reavaliar a causa."},"requiresClinicalAssessment":true,"refs":["colicSBP2025","colicSBP2023","cryRCH2025","cryNHS2026","colicNHS","infantAlarmNHS2026","acuteAbdoRCH2024","samuMS","supp_colic_sbp2023","supp_sleep_aap2026","supp_swaddle_aap2022","supp_contact_ouh2025","supp_settling_rch2025","supp_cry_nhs2026","supp_bath_nhs2026","supp_heat_nhs","supp_wind_nhs"],"home":["Use estas orientações somente depois de o bebê ser examinado e liberado para casa. Nem todo choro é cólica; a avaliação deve considerar mamadas, crescimento e sinais de doença.","Confira fome, fralda, frio, calor e necessidade de colo. Cólicas não significam que os responsáveis estejam cuidando mal do bebê."],"care":["Tente colo, contato próximo, voz baixa e movimento suave, em ambiente tranquilo. Um banho morno supervisionado pode ajudar. Nenhuma medida funciona para todos os bebês.","Para contato barriga com barriga, mantenha o bebê acordado junto ao seu tronco, com você também bem acordado. Apoie cabeça e pescoço, deixando o rosto visível e o nariz e a boca livres. Se alguém ficar sonolento, coloque o bebê no berço, de barriga para cima.","Enrolar é opcional. Só tente se a equipe ensinou a técnica e o bebê ainda não mostra sinais de tentar rolar. Use manta fina, sem peso, com cabeça e rosto descobertos, sem apertar o peito e com espaço para mexer quadris e pernas. Nunca use manta pesada.","Mesmo enrolado, o bebê deve ficar sempre de barriga para cima. Pare de enrolar ao primeiro sinal de tentar rolar. Se a manta se soltar, retire-a; não deixe tecido solto no berço. Se estiver suando ou quente demais, retire o excesso de roupa e manta.","Se o pediatra ensinou a manobra, com o bebê acordado e de barriga para cima, pode tentar dobrar suavemente as perninhas em direção à barriga, sem forçar nem apertar o abdome. Pare se houver resistência, dor ou mais choro. Não é obrigatório fazer essa manobra.","No banho, teste a água antes: ela deve estar morna, nunca quente. Fique com o bebê o tempo todo. Não use bolsa de água quente, almofada térmica nem compressa aquecida para tratar a cólica.","Reduza barulho e excesso de pessoas. Se parecer agradável ao bebê, tente música suave em volume baixo ou cante baixinho; desligue ou pare se ele ficar mais incomodado.","Organize uma rotina flexível de banho, sono e passeio, respeitando os sinais de fome, sono e cansaço do bebê. Não atrase mamadas nem force o bebê a ficar acordado para cumprir um horário.","Para dormir, coloque o bebê de barriga para cima, em berço com superfície firme e plana, sem travesseiros, objetos ou roupas cobrindo o rosto. Não o coloque de bruços para tratar a cólica.","Se estiver no limite do cansaço ou da irritação, coloque o bebê com segurança no berço e afaste-se por poucos minutos para se acalmar. Peça ajuda a outro adulto e volte para verificá-lo. Nunca sacuda o bebê."],"food":["Mantenha o leite materno ou a fórmula habitual. Não interrompa a amamentação nem troque fórmula ou retire alimentos da dieta da mãe por conta própria.","Não ofereça chá para cólica nem substitua mamadas por água ou outros alimentos. Peça ajuda se houver dificuldade na pega ou na mamada; não force a alimentação."],"course":["Após excluir doença, o choro costuma aumentar nas primeiras semanas e melhorar ao redor dos 3 a 4 meses. A cólica típica ocorre antes dos 5 meses; sintomas persistentes precisam ser revistos."],"observe":["Anote quando o choro acontece, sua duração, as mamadas e as fraldas molhadas. Observe se o bebê volta a ficar alerta entre os episódios e se está crescendo como esperado.","Não inicie remédios, misturas caseiras ou probióticos por conta própria. Se a consulta indicou algum tratamento, siga apenas aquele plano."],"alarm":["Em bebê com menos de 3 meses, temperatura de 38 °C ou mais exige atendimento imediato, mesmo que pareça bem. Febre não deve ser atribuída à cólica.","Procure atendimento sem demora se houver vômito verde, sangue no vômito ou nas fezes, barriga muito inchada, recusa de mamadas, bem menos xixi, boca seca ou sonolência incomum.","Choro que começou de repente, mudou muito ou não permite consolo, especialmente com aparência de doença, precisa de nova avaliação.","Dificuldade para respirar, coloração arroxeada, convulsão ou dificuldade para acordar: ligue 192. Se o bebê foi sacudido ou sofreu agressão, busque emergência, mesmo sem marcas aparentes.","Se você teme perder o controle e machucar o bebê, deixe-o em local seguro e peça ajuda imediatamente. Chame outro adulto de confiança e procure assistência; em risco imediato, ligue 192.","Em bebê de 3 a 6 meses, temperatura de 39 °C ou mais exige atendimento imediato. Não espere esse valor se houver sinais de alarme ou piora do estado geral."],"follow":["Cumpra o retorno combinado para rever mamadas, peso e apoio à família. Antecipe se o choro piorar, houver dificuldade para mamar ou o peso não evoluir.","Se continuar após os 4 meses, marque reavaliação. Não espere essa idade se algo parecer diferente ou você não estiver conseguindo lidar com o cansaço."],"ageInputRequired":"ageMonths for 3a5m: 3 <= ageMonths < 5"}],"updateKeys":["ext_colica_lactente"],"aliases":[{"parentKey":"bjhr_ome","alias":"Otite média com efusão"},{"parentKey":"bjhr_ome","alias":"Otite média efusiva"},{"parentKey":"pps_100","alias":"Celulite orbitária (pós-septal)"},{"parentKey":"pps_100","alias":"Celulite pós-septal"},{"parentKey":"pps_107","alias":"Hipoglicemia aguda sintomática"},{"parentKey":"pps_107","alias":"Hipoglicemia sintomática"},{"parentKey":"pps_111","alias":"Hipercalemia com alterações eletrocardiográficas"},{"parentKey":"pps_111","alias":"Hipercalemia grave com repercussão eletrocardiográfica"},{"parentKey":"pps_112","alias":"Hipocalcemia aguda (tetania)"},{"parentKey":"pps_112","alias":"Hipocalcemia aguda sintomática com tetania"},{"parentKey":"pps_119","alias":"Prono doloroso"},{"parentKey":"pps_119","alias":"Subluxação da cabeça do rádio"},{"parentKey":"pps_119","alias":"Subluxação da cabeça do rádio (prono doloroso)"},{"parentKey":"pps_131","alias":"Ingestão cáustica"},{"parentKey":"pps_131","alias":"Ingestão de cáustico"},{"parentKey":"pps_2","alias":"Rinosinusite bacteriana aguda"},{"parentKey":"pps_2","alias":"Sinusite aguda bacteriana"},{"parentKey":"pps_2","alias":"Sinusite bacteriana aguda"},{"parentKey":"pps_3","alias":"Faringoamigdalite bacteriana estreptocócica"},{"parentKey":"pps_3","alias":"Faringoamigdalite estreptocócica"},{"parentKey":"pps_34","alias":"Catapora não complicada"},{"parentKey":"pps_34","alias":"Varicela (catapora) não complicada"},{"parentKey":"pps_41","alias":"Chikungunya aguda"},{"parentKey":"pps_41","alias":"Chikungunya — fase aguda"},{"parentKey":"pps_42","alias":"Infecção aguda pelo vírus Zika"},{"parentKey":"pps_42","alias":"Zika vírus agudo"},{"parentKey":"pps_45","alias":"Sepse e choque séptico"},{"parentKey":"pps_45","alias":"Sepse pediátrica e choque séptico"},{"parentKey":"pps_49","alias":"Cefaleia primária tensional"},{"parentKey":"pps_49","alias":"Cefaleia tensional aguda"},{"parentKey":"pps_54","alias":"TCE leve sintomático"},{"parentKey":"pps_54","alias":"Traumatismo cranioencefálico leve com sintomas"},{"parentKey":"pps_70","alias":"Pediculose capitis"},{"parentKey":"pps_70","alias":"Pediculose do couro cabeludo"},{"parentKey":"pps_73","alias":"ITU baixa afebril"},{"parentKey":"pps_73","alias":"Infecção do trato urinário baixa (cistite)"},{"parentKey":"pps_73","alias":"Infecção do trato urinário inferior (cistite)"},{"parentKey":"pps_74","alias":"ITU alta aguda"},{"parentKey":"pps_74","alias":"Infecção do trato urinário alta (pielonefrite)"},{"parentKey":"pps_74","alias":"Pielonefrite aguda"},{"parentKey":"pps_89","alias":"Doença de Kawasaki aguda"},{"parentKey":"pps_89","alias":"Doença de Kawasaki em fase aguda"},{"parentKey":"pps_9","alias":"Bronquite viral aguda não complicada"},{"parentKey":"pps_97","alias":"Mastoidite aguda"}],"newCardCount":4,"checked":"2026-10-06","colicOptionalMeasureIds":["C01","C02","C03","C04","C05","C06","C07"],"recordMappings":[{"ppsId":"sinusite","parentKey":"pps_2"},{"ppsId":"outro-sinusite-aguda-bacteriana","parentKey":"pps_2"},{"ppsId":"outro-sinusite-bacteriana","parentKey":"pps_2"},{"ppsId":"catalogo-002","parentKey":"bjhr_ome"},{"ppsId":"catalogo-177","parentKey":"pps_119"},{"ppsId":"catalogo-104","parentKey":"pps_100"},{"ppsId":"mastoidite","parentKey":"pps_97"},{"ppsId":"hipoglicemia","parentKey":"pps_107"},{"ppsId":"ingestao-caustica","parentKey":"pps_131"},{"ppsId":"catalogo-010","parentKey":"pps_9"},{"ppsId":"catalogo-117","parentKey":"pps_49"},{"ppsId":"catalogo-098","parentKey":"pps_41"},{"ppsId":"kawasaki","parentKey":"pps_89"},{"ppsId":"catalogo-130","parentKey":"pps_111"},{"ppsId":"catalogo-133","parentKey":"pps_112"},{"ppsId":"pediculose","parentKey":"pps_70"},{"ppsId":"catalogo-101","parentKey":"pps_34"},{"ppsId":"catalogo-097","parentKey":"pps_42"},{"ppsId":"sepse-choque","parentKey":"pps_45"},{"ppsId":"catalogo-085","parentKey":"pps_73"},{"ppsId":"outro-anexo-infeccao-do-trato-urinario-baixa-cistite","parentKey":"pps_73"},{"ppsId":"outro-faringoamigdalite-estreptococica","parentKey":"pps_3"},{"ppsId":"outro-pielonefrite-aguda","parentKey":"pps_74"},{"ppsId":"outro-anexo-infeccao-do-trato-urinario-alta-pielonefrite","parentKey":"pps_74"},{"ppsId":"catalogo-154","parentKey":"pps_54"}]};
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const clean=(s,n=1400)=>String(s||'').replace(/[\u0000-\u001f\u007f#*]/g,' ').trim().slice(0,n);
const sources={...base.sources,...data.sources},extra=data.topics,index=new Map(),aliasIndex=new Map(),updates=new Set(data.updateKeys);
for(const t of extra){const oldKey=base.resolve(t.key);if(updates.has(t.key)&&oldKey?.key!==t.key)throw Error('Ficha a atualizar não encontrada: '+t.key);for(const value of [t.key,t.label,t.parent,...t.aliases]){const n=norm(value);if(index.has(n)&&index.get(n).key!==t.key)throw Error('Alias novo ambíguo: '+value);const old=base.resolve(value);if(old&&(!updates.has(t.key)||old.key!==t.key))throw Error('Diagnóstico já cadastrado: '+value);index.set(n,t);}}
const additions=new Map();for(const pair of data.aliases){if(!base.resolve(pair.parentKey))throw Error('Ficha de alias não encontrada: '+pair.parentKey);const n=norm(pair.alias),old=base.resolve(pair.alias);if(old&&old.key!==pair.parentKey)throw Error('Alias clínico conflitante: '+pair.alias);if(aliasIndex.has(n)&&aliasIndex.get(n)!==pair.parentKey)throw Error('Alias aprovado duplicado entre fichas');aliasIndex.set(n,pair.parentKey);if(!additions.has(pair.parentKey))additions.set(pair.parentKey,[]);additions.get(pair.parentKey).push(pair.alias);}
const topics=[...base.topics.filter(t=>!updates.has(t.key)).map(t=>additions.has(t.key)?{...t,aliases:[...new Set([...t.aliases,...additions.get(t.key)])]}:t),...extra].sort((a,b)=>a.label.localeCompare(b.label,'pt-BR'));
function resolve(v){return index.get(norm(v))||(aliasIndex.has(norm(v))?topics.find(t=>t.key===aliasIndex.get(norm(v))):base.resolve(v));}
const error=(code,message)=>({ok:false,code,message,error:message});
function build(input={}){
 const p={...input},name=norm(p.diagnosis),t=index.get(name);
 if(!t)return base.build(aliasIndex.has(name)?{...p,diagnosis:aliasIndex.get(name)}:p);
 if(p.danger==='yes'||(p.age==='u3m'&&p.fever==='yes'))return base.build({...p,diagnosis:'resfriado'});
 const age=p.age||'unknown';if(!Object.hasOwn(base.ages,age))return error('AGE_INVALID','Selecione uma faixa etária válida.');
 if(t.key==='ext_colica_lactente'){
  if(!['u3m','3a5m'].includes(age))return error('COLIC_AGE_REVIEW','A ficha de cólica exige idade confirmada menor que 5 meses. Confira a idade e reavalie outras causas de choro.');
  const raw=String(p.ageMonths??'').trim().replace(',','.');const months=/^\d+(?:\.\d+)?$/.test(raw)?Number(raw):NaN;
  if(age==='u3m'&&raw!==''&&(!Number.isFinite(months)||months<0||months>=3))return error('COLIC_AGE_CONFLICT','A idade exata informada não corresponde à faixa menor de 3 meses. Confira os dados antes de gerar a orientação.');
  if(age==='3a5m'&&(!Number.isFinite(months)||months<3||months>=5))return error('COLIC_EXACT_AGE_REQUIRED','Para cólica na faixa de 3 a 5 meses, informe a idade exata em meses: esta ficha só se aplica antes de completar 5 meses.');
 }
 const urgent=t.urgency||(t.conditionalTriage&&p.reviewed!==true);
 if(!urgent&&p.reviewed!==true)return error('REVIEW_REQUIRED','Confirme que a criança foi avaliada e liberada para cuidados em casa.');
 const sections=[];function add(title,items){if(items&&items.length)sections.push({title,items:[...new Set(items)]});}
 add(urgent?'AVALIAÇÃO PRESENCIAL SEM DEMORA':'CUIDADOS EM CASA',[...(t.detail?[t.detail]:[]),...(t.home||[])]);
 add(urgent?'ENQUANTO BUSCA AJUDA':'MEDIDAS SEM REMÉDIOS',t.care);
 add('ALIMENTAÇÃO E LÍQUIDOS',t.food);add('O QUE ESPERAR',t.course);add('O QUE OBSERVAR',t.observe);
 const alarms=[...(t.alarm||[])];if(['unknown','u3m'].includes(age)&&!alarms.some(s=>/menos de 3 meses/.test(s)))alarms.push('Em bebê com menos de 3 meses, temperatura de 38 °C ou mais exige avaliação imediata, mesmo que pareça bem.');
 add(urgent?'SINAIS GRAVES E QUANDO BUSCAR SOCORRO':'VOLTE IMEDIATAMENTE AO PRONTO ATENDIMENTO',alarms);
 const follow=[...(t.follow||[])];if(p.risk==='yes')follow.push('Por haver condição de risco, antecipe a reavaliação diante de qualquer piora.');if(!urgent&&clean(p.returnPlan,200))follow.push('Retorno combinado na consulta: '+clean(p.returnPlan,200));
 add(urgent?'CONTINUIDADE DO CUIDADO':'QUANDO REAVALIAR',follow);
 if(!urgent&&clean(p.notes))add('COMPLEMENTO DA CONSULTA',[clean(p.notes)]);
 const heading=urgent?'ORIENTAÇÕES AOS PAIS — '+t.label:'ORIENTAÇÕES AOS PAIS\n'+t.parent+(age==='unknown'?'':'\nFaixa etária: '+base.ages[age]);
 const text=heading+'\n\n'+sections.map((s,i)=>(i+1)+'. '+s.title+'\n'+s.items.map(x=>(urgent?'• ':'- ')+x).join('\n')).join('\n\n')+(urgent?'':'\n\nEstas orientações complementam a consulta e não substituem o tratamento prescrito.');
 return {ok:true,mode:urgent?'urgent':'guidance',topic:t.key,label:t.label,sections,refs:[...t.refs],text};
}
const testAge=t=>index.has(norm(t.key))?(t.key==='ext_colica_lactente'?'u3m':'2a5'):base.testAge(t);
function audit(){const old=base.audit(),issues=[...(old.issues||[])];for(const t of extra){const r=build({diagnosis:t.key,age:testAge(t),reviewed:true});if(!r.ok||r.text.length<150||r.refs.some(x=>!sources[x]))issues.push(t.key);if(t.urgency&&r.mode!=='urgent')issues.push(t.key+':urgency');}if(new Set(topics.map(t=>t.key)).size!==topics.length)issues.push('duplicate-keys');return {...old,ok:issues.length===0,issues,topics:topics.length,secondBatchAdded:data.newCardCount,urgent:topics.filter(t=>t.urgency).length};}
